"  var b=nsecDecode(v.trim());\n"
"  if(!b||b2n(b)===0n||b2n(b)>=N){snack('That is not a valid nsec');return;}\n"
"  useKey(b);identSent=0;seen={};\n"
"  document.getElementById('msgs').innerHTML='';\n"
"  snack('Now chatting as '+mycall);load();}\n"
"function newIdentity(){toggleMenu();\n"
"  useKey(randKey());identSent=0;seen={};\n"
"  document.getElementById('msgs').innerHTML='';\n"
"  snack('New identity: '+mycall);load();}\n"
"\n"
"// ---- XPRS wires ----\n"
"function tsNow(){\n"
"  var d=new Date(),p=function(n){return (n<10?'0':'')+n;};\n"
"  return d.getUTCFullYear()+'-'+p(d.getUTCMonth()+1)+'-'+p(d.getUTCDate())+\n"
"    '_'+p(d.getUTCHours())+':'+p(d.getUTCMinutes())+':'+p(d.getUTCSeconds());}\n"
"function aux32(){var b=new Uint8Array(32);\n"
"  if(window.crypto&&crypto.getRandomValues)crypto.getRandomValues(b);\n"
"  else for(var i=0;i<32;i++)b[i]=Math.floor(Math.random()*256);return b;}\n"
"function signWire(canonical){\n"
"  var sig=' sig:'+b85enc(xprsSign(canonical,b2n(priv),aux32()));\n"
"  var i=canonical.indexOf(' m:');\n"
"  if(i>=0)return canonical.slice(0,i)+sig+canonical.slice(i);\n"
"  return canonical+sig;}\n"
"\n"
"// ---- sending: POST -> GET -> Image() (hostile WebViews) ----\n"
"function postWire(wire,cb){\n"
"  var done=false;\n"
"  function fin(ok){if(!done){done=true;if(cb)cb(ok);}}\n"
"  try{\n"
"    var x=new XMLHttpRequest();\n"
"    x.open('POST','/api/xprs/send',true);\n"
"    x.timeout=4000;\n"
"    x.onload=function(){fin(x.status===200);};\n"
"    x.onerror=x.ontimeout=function(){getFallback(wire,fin);};\n"
"    x.send(JSON.stringify({wire:wire}));\n"
"  }catch(e){getFallback(wire,fin);}\n"
"}\n"
"function getFallback(wire,fin){\n"
"  try{\n"
"    var x=new XMLHttpRequest();\n"
"    x.open('GET','/api/xprs/send?wire='+encodeURIComponent(wire),true);\n"
"    x.timeout=4000;\n"
"    x.onload=function(){fin(x.status===200);};\n"
"    x.onerror=x.ontimeout=function(){\n"
"      try{new Image().src='/api/xprs/send?wire='+encodeURIComponent(wire);}catch(e){}\n"
"      fin(true);};\n"
"    x.send();\n"
"  }catch(e){fin(false);}\n"
"}\n"
"\n"
"var identSent=0;\n"
"function sendIdentity(){\n"
"  var now=Date.now();\n"
"  if(now-identSent<86400000)return;\n"
"  identSent=now;\n"
"  postWire(signWire('t:identity f:'+mycall+' ts:'+tsNow()+' k:'+npub),null);\n"
"}\n"
"function sendMsg(){\n"
"  var t=document.getElementById('txt');\n"
"  var text=t.value.trim();\n"
"  if(!text||!priv)return;\n"
"  text=text.replace(/[\\x00-\\x1f]/g,' ');\n"
"  sendIdentity();\n"
"  var wire=signWire('t:message f:'+mycall+' ts:'+tsNow()+' m:'+text);\n"
"  if(wire.length>250){snack('Message too long');return;}\n"
"  t.value='';\n"
"  /* On the screen immediately -- the archive round trip (index writer +\n"
"   * the next poll) takes seconds, and a sender should not wait on it.\n"
"   * The wire is archived verbatim, so marking it seen dedups the echo. */\n"
"  render({from:mycall,ts:Math.floor(Date.now()/1000),sig:'verified',wire:wire});\n"
"  postWire(wire,function(ok){\n"
"    if(!ok)snack('Send failed');});\n"
"}\n"
"\n"
"// ---- receiving ----\n"
"var seen={};\n"
"var clearedBefore=parseInt(stGet('xprs_cleared')||'0',10)||0;\n"
"function render(row){\n"
"  var w=row.wire||'';\n"
"  if(seen[w])return;seen[w]=1;\n"
"  var mi=w.indexOf(' m:');\n"
"  var text=mi>=0?w.slice(mi+3):'';\n"
"  if(!text)return;\n"
"  if(clearedBefore&&(row.ts||0)<clearedBefore)return;   /* user hit Clear */\n"
"  var own=row.from===mycall;\n"
"  var d=document.createElement('div');\n"
"  d.className='msg '+(own?'local':'remote');\n"
"  var when=row.ts?new Date(row.ts*1000).toLocaleTimeString():'';\n"
"  var badge=row.sig==='verified'?'<span class=\"badge ok\">signed</span>'\n"
"           :(row.sig==='none'?'<span class=\"badge bad\">unsigned</span>':'');\n"
"  if(own){\n"
"    /* Own messages: the balloon speaks for itself -- no callsign, and the\n"
"     * timestamp sits quietly underneath. */\n"
"    d.innerHTML='<div class=\"bubble\"></div>'+\n"
"      '<div class=\"meta under\"><span class=\"time\">'+when+'</span>'+badge+'</div>';\n"
"  }else{\n"
"    d.innerHTML='<div class=\"meta\"><span class=\"author\"></span>'+\n"
"      '<span class=\"time\">'+when+'</span>'+badge+'</div>'+\n"
"      '<div class=\"bubble\"></div>';\n"
"    d.querySelector('.author').textContent=row.from;\n"
"  }\n"
"  d.querySelector('.bubble').textContent=text;\n"
"  var box=document.getElementById('msgs');\n"
"  box.appendChild(d);\n"
"  box.scrollTop=box.scrollHeight;\n"
"}\n"
"function clearChat(){\n"
"  toggleMenu();\n"
"  clearedBefore=Math.floor(Date.now()/1000);\n"
"  stSet('xprs_cleared',''+clearedBefore);\n"
"  seen={};\n"
"  document.getElementById('msgs').innerHTML='';\n"
"  snack('Chat view cleared');\n"
"}\n"
"function load(){\n"
"  try{\n"
"    var x=new XMLHttpRequest();\n"
"    x.open('GET','/api/xprs/history?only=message&limit=50',true);\n"
"    x.timeout=4000;\n"
"    x.onload=function(){\n"
"      try{\n"
"        var d=JSON.parse(x.responseText);\n"
"        var rows=(d.rows||[]).slice().reverse();\n"
"        for(var i=0;i<rows.length;i++)render(rows[i]);\n"
"        document.getElementById('stat').textContent=\n"
"          (d.held!==undefined?d.held+' packets held':'ok');\n"
"      }catch(e){}\n"
"    };\n"
"    x.send();\n"
"  }catch(e){}\n"
"}\n"
"\n"
"// ---- boot: an identity exists before the first keystroke ----\n"
"(function(){\n"
"  var saved=stGet('xprs_nsec');\n"
"  var b=saved?nsecDecode(saved):null;\n"
"  useKey(b||randKey());\n"
"  load();\n"
"  setInterval(load,3000);\n"
"})();\n"
"</script></body></html>\n"
"\n";

const size_t XPRS_CHAT_PAGE_LEN = sizeof(XPRS_CHAT_PAGE) - 1;
